Method.Source:
/// <summary>
///    AVA <c>runService</c> method.
/// </summary>
public void runService()
{
    AVABPRequestsAutomaticRefusal   locAVABPRequestsAutomaticRefusal;

    #OCCRetryCount


    lJobMode    = false;

    if(this.isExecutingInBatch())
    {
        lJobMode    = true;
    }

    try
    {
        runtime = DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone());

        locAVABPRequestsAutomaticRefusal = new AVABPRequestsAutomaticRefusal();

        locAVABPRequestsAutomaticRefusal.init();
        locAVABPRequestsAutomaticRefusal.run();

        runtime = DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()) - runtime;

        info(strfmt("@NDX:NXABPRequestAutomaticRefusedRuntimeP1", runtime));
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}
